import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@200;300;400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type MinimalFinancialTickerProps = Record<string, any>;

const MinimalFinancialTicker: React.FC<MinimalFinancialTickerProps> = ({
  backgroundColor = "#030305",
  transparentBackground = false,
  durationInSeconds = 8,
  targetPercentage = 20,
  primaryColor = "#ffffff",
  secondaryTextColor = "#8a8a93",
  label = "ANNUAL YIELD RETURN",
  showDashboardGrid = true,
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Lato"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety logic for transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const introDuration = fps * 1.5;
  const startCountingFrame = Math.round(fps * 0.8);
  
  // Entrance Animation
  const entranceProgress = spring({
    frame,
    fps,
    config: { damping: 100, stiffness: 200, mass: 1.5 },
  });

  const mainOpacity = interpolate(entranceProgress, [0, 1], [0, 1]);
  const containerTranslateY = interpolate(entranceProgress, [0, 1], [40, 0]);

  // Ticker Animation
  // We use a very smooth, slow spring to simulate financial data stabilizing
  const tickerSpring = spring({
    frame: frame - startCountingFrame,
    fps,
    config: { damping: 150, stiffness: 40, mass: 3 },
  });

  const currentPercentage = tickerSpring * targetPercentage;
  
  // Formatting to rounded numbers without decimals
  const displayValue = Math.round(currentPercentage).toString();

  // Generate tick marks for the dashboard scale (0 to 100 in steps of 2)
  const ticks = Array.from({ length: 51 }).map((_, i) => i * 2);

  // Grid fade in
  const gridOpacity = interpolate(
    frame,
    [0, introDuration],
    [0, 0.15],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        fontFamily: "Lato, sans-serif",
        color: primaryColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden"
      }}
    >
      {/* Subtle Background Grid */}
      {showDashboardGrid && (
        <AbsoluteFill style={{ opacity: gridOpacity, pointerEvents: "none" }}>
          {Array.from({ length: 20 }).map((_, i) => (
            <div 
              key={`h-line-${i}`}
              style={{
                position: "absolute",
                top: `${(i / 19) * 100}%`,
                left: 0,
                right: 0,
                height: 1,
                backgroundColor: primaryColor,
                opacity: i % 5 === 0 ? 0.2 : 0.05,
                transition: "none"
              }}
            />
          ))}
          {Array.from({ length: 30 }).map((_, i) => (
            <div 
              key={`v-line-${i}`}
              style={{
                position: "absolute",
                left: `${(i / 29) * 100}%`,
                top: 0,
                bottom: 0,
                width: 1,
                backgroundColor: primaryColor,
                opacity: i % 5 === 0 ? 0.15 : 0.03,
                transition: "none"
              }}
            />
          ))}
        </AbsoluteFill>
      )}

      {/* Main Content Container */}
      <div 
        style={{
          width: width * 0.65,
          opacity: mainOpacity,
          transform: `translateY(${containerTranslateY}px)`,
          display: "flex",
          flexDirection: "column",
          gap: "24px",
          transition: "none",
        }}
      >
        {/* Header Section: Label & Ticker */}
        <div style={{
          display: "flex",
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "baseline",
          transition: "none",
        }}>
          
          <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
            <div style={{
              fontSize: "16px",
              fontWeight: 500,
              letterSpacing: "0.2em",
              color: secondaryTextColor,
              textTransform: "uppercase",
              transition: "none",
            }}>
              {label}
            </div>
            
            <div style={{
              display: "flex",
              alignItems: "baseline",
              transition: "none",
            }}>
              <span style={{
                fontSize: "140px",
                fontWeight: 200,
                fontVariantNumeric: "tabular-nums",
                lineHeight: 0.9,
                letterSpacing: "-0.02em",
                textShadow: `0 0 40px ${primaryColor}40`,
                transition: "none",
              }}>
                {displayValue}
              </span>
              <span style={{
                fontSize: "64px",
                fontWeight: 300,
                marginLeft: "8px",
                color: secondaryTextColor,
                transition: "none",
              }}>
                %
              </span>
            </div>
          </div>

          <div style={{
            fontSize: "14px",
            color: secondaryTextColor,
            fontVariantNumeric: "tabular-nums",
            textAlign: "right",
            lineHeight: 1.5,
            transition: "none",
          }}>
            TARGET<br/>
            <span style={{ color: primaryColor, fontWeight: 500 }}>{Math.round(targetPercentage)}%</span>
          </div>
        </div>

        {/* Progress Bar Section */}
        <div style={{
          position: "relative",
          width: "100%",
          height: "60px", // Increased height to accommodate tick marks
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-end",
          transition: "none",
        }}>
          
          {/* Top Tick Marks */}
          <div style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            height: "20px",
            transition: "none",
          }}>
            {ticks.map((tickValue) => {
              const isMajor = tickValue % 10 === 0;
              return (
                <div 
                  key={`tick-${tickValue}`}
                  style={{
                    position: "absolute",
                    left: `${tickValue}%`,
                    bottom: "4px",
                    width: "1px",
                    height: isMajor ? "16px" : "8px",
                    backgroundColor: primaryColor,
                    opacity: isMajor ? 0.4 : 0.15,
                    transform: "translateX(-50%)",
                    transition: "none",
                  }}
                >
                  {isMajor && (
                    <div style={{
                      position: "absolute",
                      top: "-20px",
                      left: "50%",
                      transform: "translateX(-50%)",
                      fontSize: "10px",
                      color: secondaryTextColor,
                      fontVariantNumeric: "tabular-nums",
                      transition: "none",
                    }}>
                      {tickValue}
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          {/* Track Background */}
          <div style={{
            position: "relative",
            width: "100%",
            height: "2px",
            backgroundColor: `${primaryColor}20`,
            borderRadius: "2px",
            overflow: "hidden",
            transition: "none",
          }}>
            
            {/* Active Fill */}
            <div style={{
              position: "absolute",
              left: 0,
              top: 0,
              bottom: 0,
              width: `${currentPercentage}%`,
              backgroundColor: primaryColor,
              boxShadow: `0 0 10px ${primaryColor}, 0 0 20px ${primaryColor}80`,
              transition: "none",
            }} />
          </div>

          {/* Glowing Lead Indicator */}
          <div style={{
            position: "absolute",
            left: `${currentPercentage}%`,
            bottom: "-3px",
            width: "8px",
            height: "8px",
            backgroundColor: primaryColor,
            borderRadius: "50%",
            transform: "translateX(-50%)",
            boxShadow: `0 0 15px 4px ${primaryColor}60`,
            opacity: currentPercentage > 0.1 ? 1 : 0,
            transition: "none",
          }} />

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MinimalFinancialTicker;